// Raw question banks are declared without `year` — it is attached once, in bulk,
// when the exported legalQuizBanks are assembled at the bottom of this file.
type RawLegalQuizQuestion = Omit<LegalQuizQuestion, 'year'>;

const withYear = (items: RawLegalQuizQuestion[], year: LegalQuizYear): LegalQuizQuestion[] =>
  items.map((item) => ({ ...item, year }));

