const crimeMcq: RawLegalQuizQuestion[] = [
  { id: 'crime-mcq-01', topic: 'crime', syllabusArea: 'Nature of crime', type: 'multiple-choice', prompt: 'A man is charged after CCTV shows him striking another patron outside a bar. The prosecution must prove both that he threw the punch and that he intended to cause harm. These two elements are known as', options: ['actus reus and mens rea', 'bail and remand', 'trial and appeal', 'police and courts'], answer: 'actus reus and mens rea', explanation: 'Most crimes require proof of both a guilty act (actus reus) and a guilty mind (mens rea).' },
  { id: 'crime-mcq-02', topic: 'crime', syllabusArea: 'Nature of crime', type: 'multiple-choice', prompt: 'In a shoplifting trial, the prosecution presents CCTV footage showing the accused physically placing goods in her bag without paying. This evidence is most directly relevant to proving', options: ['actus reus', 'mens rea', 'the final sentence', 'the appeal process'], answer: 'actus reus', explanation: 'Actus reus is the physical act or omission element of a crime.' },
  { id: 'crime-mcq-03', topic: 'crime', syllabusArea: 'Nature of crime', type: 'multiple-choice', prompt: 'A defendant argues he did not realise the goods he was carrying were stolen. If accepted, this argument would most directly challenge the prosecution’s case on', options: ['mens rea', 'actus reus', 'the victim impact statement', 'the court hierarchy'], answer: 'mens rea', explanation: 'Mens rea is the mental element of a crime — here, whether the accused knew the goods were stolen.' },
  { id: 'crime-mcq-04', topic: 'crime', syllabusArea: 'Nature of crime', type: 'multiple-choice', prompt: 'A driver is charged after a fatal collision caused by reckless overtaking, with prosecutors alleging an unlawful killing without premeditation. This charge would most likely fall under', options: ['offences against the person', 'economic offences', 'public order offences', 'drug offences'], answer: 'offences against the person', explanation: 'Homicide offences, including manslaughter, are classified as offences against the person.' },
  { id: 'crime-mcq-05', topic: 'crime', syllabusArea: 'Nature of crime', type: 'multiple-choice', prompt: 'A citizen is charged after allegedly passing classified defence information to a hostile foreign government during wartime. This offence is best classified as', options: ['treason', 'larceny', 'assault', 'perjury'], answer: 'treason', explanation: 'Treason is a classic offence against the sovereign, involving betrayal of one’s own state.' },
  { id: 'crime-mcq-06', topic: 'crime', syllabusArea: 'Nature of crime', type: 'multiple-choice', prompt: 'A cafe owner is fined for selling food past its use-by date, even though she genuinely believed the stock was still safe to sell. This scenario illustrates an offence where', options: ['mens rea does not need to be proven', 'a jury must be empanelled', 'the matter must be indictable', 'no penalty can apply'], answer: 'mens rea does not need to be proven', explanation: 'Strict liability offences remove the need to prove mens rea, focusing on the act itself.' },
  { id: 'crime-mcq-07', topic: 'crime', syllabusArea: 'Nature of crime', type: 'multiple-choice', prompt: 'After a robbery, police charge not only the person who entered the store, but also the getaway driver who waited outside knowing the plan. The driver is best described as', options: ['a party to the crime', 'a judge', 'a juror', 'a victim'], answer: 'a party to the crime', explanation: 'Parties to a crime include accessories, such as those who assist or facilitate an offence.' },
  { id: 'crime-mcq-08', topic: 'crime', syllabusArea: 'Nature of crime', type: 'multiple-choice', prompt: 'Criminologists studying reoffending rates in a disadvantaged suburb point to unemployment and lack of access to education as contributing conditions. This reflects the influence of', options: ['social and economic factors on criminal behaviour', 'court architecture', 'the colour of court uniforms', 'the name of the statute alone'], answer: 'social and economic factors on criminal behaviour', explanation: 'Social and economic disadvantage is commonly discussed as a factor influencing criminal behaviour.' },
  { id: 'crime-mcq-09', topic: 'crime', syllabusArea: 'Criminal investigation process', type: 'multiple-choice', prompt: 'NSW Police stop and search a vehicle after receiving a tip-off about stolen goods inside. The legislation setting out the scope of this police power is', options: ['LEPRA', 'the UDHR', 'the ICESCR', 'the Family Law Act'], answer: 'LEPRA', explanation: 'The Law Enforcement (Powers and Responsibilities) Act (LEPRA) regulates many NSW police powers.' },
  { id: 'crime-mcq-10', topic: 'crime', syllabusArea: 'Criminal investigation process', type: 'multiple-choice', prompt: 'An accused person is released from custody ahead of his trial date, on condition that he reports weekly to a police station and does not contact witnesses. This is an example of', options: ['bail', 'a final sentence', 'an appeal', 'a police investigation'], answer: 'bail', explanation: 'Bail allows an accused person’s release before trial, generally subject to conditions.' },
  { id: 'crime-mcq-11', topic: 'crime', syllabusArea: 'Criminal investigation process', type: 'multiple-choice', prompt: 'Detectives investigating a break-in enter a suspect’s home and remove a laptop believed to contain evidence. This action is an example of', options: ['search and seizure', 'a jury verdict', 'a sentencing discount', 'parliamentary debate'], answer: 'search and seizure', explanation: 'Police powers include search and seizure, arrest, detention and questioning.' },
  { id: 'crime-mcq-12', topic: 'crime', syllabusArea: 'Criminal investigation process', type: 'multiple-choice', prompt: 'Before entering a suspect’s premises to search for drugs, police apply to a magistrate for a document authorising the search. This document is called a', options: ['warrant', 'verdict', 'penalty notice', 'jury'], answer: 'warrant', explanation: 'Warrants authorise specific police actions, such as a search or an arrest.' },
  { id: 'crime-mcq-13', topic: 'crime', syllabusArea: 'Criminal trial process', type: 'multiple-choice', prompt: 'At the close of a murder trial, the judge directs the jury that they can only convict if they are sure of the accused’s guilt, with no reasonable alternative explanation. This reflects the standard of', options: ['beyond reasonable doubt', 'the balance of probabilities', 'suspicion only', 'media reporting'], answer: 'beyond reasonable doubt', explanation: 'Beyond reasonable doubt is the criminal standard of proof required for conviction.' },
  { id: 'crime-mcq-14', topic: 'crime', syllabusArea: 'Criminal trial process', type: 'multiple-choice', prompt: 'In a criminal trial, the accused is not required to prove his innocence — instead, it is up to the other side to establish guilt. Which party carries this burden?', options: ['The prosecution', 'The accused', 'The jury', 'The media'], answer: 'The prosecution', explanation: 'The prosecution generally bears the burden of proving the accused’s guilt.' },
  { id: 'crime-mcq-15', topic: 'crime', syllabusArea: 'Criminal trial process', type: 'multiple-choice', prompt: 'At his first court appearance, an accused person tells the magistrate he committed the offence and does not wish to contest the charge. This is best described as a plea of', options: ['guilty', 'not guilty', 'bail', 'appeal'], answer: 'guilty', explanation: 'A guilty plea admits the offence and usually moves the matter directly to sentencing.' },
  { id: 'crime-mcq-16', topic: 'crime', syllabusArea: 'Criminal trial process', type: 'multiple-choice', prompt: 'Facing two charges, an accused agrees to plead guilty to the lesser charge in exchange for the prosecution dropping the more serious one. This process is known as', options: ['charge negotiation', 'a jury vote', 'an unlawful search', 'a prison program'], answer: 'charge negotiation', explanation: 'Charge negotiation (plea bargaining) can resolve matters without a full trial.' },
  { id: 'crime-mcq-17', topic: 'crime', syllabusArea: 'Criminal trial process', type: 'multiple-choice', prompt: 'Twelve members of the public listen to weeks of evidence in a robbery trial before retiring to decide whether the prosecution has proven its case. Their role is to', options: ['determine facts and deliver a verdict', 'draft legislation', 'arrest suspects', 'set parole conditions'], answer: 'determine facts and deliver a verdict', explanation: 'Juries decide whether guilt is proven based on evidence and judicial directions, delivering a verdict.' },
  { id: 'crime-mcq-18', topic: 'crime', syllabusArea: 'Criminal trial process', type: 'multiple-choice', prompt: 'A man charged with assault argues he only struck the other person because he reasonably believed his life was in immediate danger. If accepted, this argument could operate as', options: ['a complete defence of self-defence', 'a media interview', 'a purpose of punishment', 'a committal mention'], answer: 'a complete defence of self-defence', explanation: 'Self-defence can operate as a complete defence, excusing criminal responsibility if established.' },
  { id: 'crime-mcq-19', topic: 'crime', syllabusArea: 'Criminal trial process', type: 'multiple-choice', prompt: 'A defendant charged with murder has his matter committed for trial to the court that hears the most serious indictable offences in NSW. This is the', options: ['Supreme Court', 'Local Court small claims division', 'Children’s Court', 'NCAT'], answer: 'Supreme Court', explanation: 'The Supreme Court handles the most serious criminal matters in NSW, including murder.' },
  { id: 'crime-mcq-20', topic: 'crime', syllabusArea: 'Sentencing and punishment', type: 'multiple-choice', prompt: 'A judge imposes a lengthy sentence partly to send a clear message discouraging others in the community from committing similar offences. This purpose of punishment is known as', options: ['deterrence', 'ratification', 'universal suffrage', 'sovereignty'], answer: 'deterrence', explanation: 'Deterrence aims to discourage the offender and the wider community from committing crime.' },
  { id: 'crime-mcq-21', topic: 'crime', syllabusArea: 'Sentencing and punishment', type: 'multiple-choice', prompt: 'As part of his sentence, an offender is required to complete a drug treatment program aimed at addressing the addiction that led to his offending. This best reflects the purpose of', options: ['rehabilitation', 'increasing media coverage', 'avoiding legal consequences', 'replacing the trial process'], answer: 'rehabilitation', explanation: 'Rehabilitation focuses on reforming offenders and addressing the causes of their offending to reduce reoffending.' },
  { id: 'crime-mcq-22', topic: 'crime', syllabusArea: 'Sentencing and punishment', type: 'multiple-choice', prompt: 'Before sentencing, the court reads a written account from the victim’s family describing the lasting emotional and financial impact of the offence. This document is known as a', options: ['victim impact statement', 'definition of actus reus', 'statement on the right to vote', 'international treaty'], answer: 'victim impact statement', explanation: 'Victim impact statements may inform sentencing by showing the harm caused to victims.' },
  { id: 'crime-mcq-23', topic: 'crime', syllabusArea: 'Sentencing and punishment', type: 'multiple-choice', prompt: 'Rather than being sent to prison, an offender is ordered to complete 200 hours of unpaid work in the community and remain under supervision for 18 months. This sentencing outcome is an example of a', options: ['community correction order', 'full-time imprisonment order', 'extradition treaty', 'jury empanelment'], answer: 'community correction order', explanation: 'Community correction orders are non-custodial sentencing alternatives to full-time imprisonment.' },
  { id: 'crime-mcq-24', topic: 'crime', syllabusArea: 'Young offenders', type: 'multiple-choice', prompt: 'A 15-year-old caught shoplifting for the first time is issued a formal police caution instead of being charged and taken to court. This response reflects the principle of', options: ['diversion where appropriate', 'mandatory adult imprisonment for all matters', 'removing all police discretion', 'excluding rehabilitation'], answer: 'diversion where appropriate', explanation: 'Young offender systems often emphasise diversion away from formal court processes where appropriate.' },
  { id: 'crime-mcq-25', topic: 'crime', syllabusArea: 'Young offenders', type: 'multiple-choice', prompt: 'A 16-year-old charged with assault has his matter heard in a closed courtroom by a specialist magistrate, with the media restricted from identifying him. This is most likely occurring in the', options: ['Children’s Court', 'High Court', 'International Criminal Court', 'Coroner’s Court'], answer: 'Children’s Court', explanation: 'The Children’s Court hears many matters involving young offenders, often with restricted publicity.' },
  { id: 'crime-mcq-26', topic: 'crime', syllabusArea: 'International crime', type: 'multiple-choice', prompt: 'A military commander is accused of ordering the systematic killing of an ethnic group with the intent to destroy it entirely. This alleged offence is best classified as', options: ['genocide', 'a parking offence', 'a bail variation', 'a local noise complaint'], answer: 'genocide', explanation: 'Genocide is a recognised international crime involving intent to destroy a protected group.' },
  { id: 'crime-mcq-27', topic: 'crime', syllabusArea: 'International crime', type: 'multiple-choice', prompt: 'After a state proves unwilling to prosecute its own former leader for war crimes, the matter is referred to an international body based in The Hague. This body is the', options: ['International Criminal Court', 'NSW Local Court', 'Fair Work Commission', 'Land and Environment Court'], answer: 'International Criminal Court', explanation: 'The ICC prosecutes certain serious international crimes, including war crimes and genocide.' },
  { id: 'crime-mcq-28', topic: 'crime', syllabusArea: 'International crime', type: 'multiple-choice', prompt: 'A fraud suspect who fled to another country is formally surrendered back to face charges after a legal process between the two governments. This process is known as', options: ['extradition', 'jury selection', 'automatic bail', 'treaty drafting'], answer: 'extradition', explanation: 'Extradition is the formal surrender of a person to another jurisdiction for prosecution or punishment.' },
  { id: 'crime-mcq-29', topic: 'crime', syllabusArea: 'Sentencing and punishment', type: 'multiple-choice', prompt: 'Two offenders committed similar break-ins, but one immediately pleaded guilty and expressed remorse, while the other contested the charge until the trial’s final day. The first offender is more likely to receive a reduced sentence because of', options: ['an early guilty plea as a mitigating factor', 'greater harm to the victim', 'prior similar convictions', 'evidence of planning the offence'], answer: 'an early guilty plea as a mitigating factor', explanation: 'An early guilty plea is a mitigating factor that may reduce sentence, reflecting remorse and saving court resources.' },
  { id: 'crime-mcq-30', topic: 'crime', syllabusArea: 'Criminal trial process', type: 'multiple-choice', prompt: 'In an Australian criminal trial, the prosecution and defence each present evidence and test the other side’s case, while the judge acts as a neutral referee rather than an investigator. This system is known as the', options: ['adversarial system', 'inquisitorial system', 'restorative system', 'federal system'], answer: 'adversarial system', explanation: 'The adversarial system features contest between prosecution and defence before an impartial court.' },
];

