const legalSystem: RawLegalQuizQuestion[] = [
  { id: 'y11-ls-01', topic: 'legalSystem', syllabusArea: 'Basic legal concepts', type: 'multiple-choice', prompt: 'A workplace has an unwritten expectation that staff greet customers within 30 seconds, but no rule requiring it is ever written down or enforced by a court. This expectation is best described as', options: ['a custom or convention rather than law', 'statute law', 'a source of delegated legislation', 'a precedent'], answer: 'a custom or convention rather than law', explanation: 'Not every social rule is law — law is a body of rules enforceable through state institutions, unlike custom or convention.' },
  { id: 'y11-ls-02', topic: 'legalSystem', syllabusArea: 'Basic legal concepts', type: 'multiple-choice', prompt: 'A new law requires large corporations to disclose their carbon emissions annually, with fines for non-compliance enforced by a government regulator. This best illustrates that, unlike ethics or custom, law is', options: ['binding and enforceable by the state', 'always identical to community morality', 'created only by courts', 'optional for large organisations'], answer: 'binding and enforceable by the state', explanation: 'A defining feature of law is that it is binding and can be enforced through state mechanisms, unlike purely moral or customary rules.' },
  { id: 'y11-ls-03', topic: 'legalSystem', syllabusArea: 'Basic legal concepts', type: 'multiple-choice', prompt: 'A visitor to Australia is arrested for an offence and is guaranteed the same right to a fair hearing as an Australian citizen would receive. This best reflects the principle that', options: ['everyone is equally subject to and protected by the law (rule of law)', 'parliament is above the law', 'only citizens have legal rights', 'courts may ignore legislation if they disagree with it'], answer: 'everyone is equally subject to and protected by the law (rule of law)', explanation: 'The rule of law holds that all people, including visitors and government, are equally bound by and entitled to the protection of the law.' },
  { id: 'y11-ls-04', topic: 'legalSystem', syllabusArea: 'Basic legal concepts', type: 'multiple-choice', prompt: 'A court is criticised after a technically lawful decision leaves a genuinely deserving party with no remedy at all. Commentators argue the outcome was legally correct but not', options: ['just', 'binding', 'valid', 'enforceable'], answer: 'just', explanation: 'Justice concerns whether a legal outcome is fair, which can be distinct from whether it is technically valid or lawful.' },
  { id: 'y11-ls-05', topic: 'legalSystem', syllabusArea: 'Basic legal concepts', type: 'multiple-choice', prompt: 'Australia’s legal system relies on both parliament-made statutes and judge-made decisions that can be looked up and applied to later, similar cases. This system is best described as a', options: ['common law system', 'civil law system', 'religious law system', 'customary law system only'], answer: 'common law system', explanation: 'Australia has a common law system, combining statute law with judge-made law built on precedent.' },
  { id: 'y11-ls-06', topic: 'legalSystem', syllabusArea: 'Sources of law', type: 'multiple-choice', prompt: 'The NSW Parliament debates and passes a new Act increasing penalties for illegal firearm possession. This law is an example of', options: ['statute law', 'common law', 'delegated legislation', 'customary law'], answer: 'statute law', explanation: 'Statute law is law made directly by parliament through the passage of Acts.' },
  { id: 'y11-ls-07', topic: 'legalSystem', syllabusArea: 'Sources of law', type: 'multiple-choice', prompt: 'A High Court decision establishes a new legal principle about when an employer is liable for an employee’s actions. Future lower courts facing similar facts are expected to apply this principle. This body of law is best described as', options: ['common law (case law)', 'statute law', 'delegated legislation', 'a treaty'], answer: 'common law (case law)', explanation: 'Common law develops through court decisions that create precedents to be applied in future similar cases.' },
  { id: 'y11-ls-08', topic: 'legalSystem', syllabusArea: 'Sources of law', type: 'multiple-choice', prompt: 'A District Court judge hearing a negligence claim is required to follow a relevant principle previously established by the High Court, even though she personally disagrees with it. This obligation reflects the', options: ['doctrine of precedent', 'principle of causation', 'concept of mens rea', 'rule against delegated legislation'], answer: 'doctrine of precedent', explanation: 'The doctrine of precedent requires lower courts to follow relevant decisions of higher courts within the same hierarchy.' },
  { id: 'y11-ls-09', topic: 'legalSystem', syllabusArea: 'Sources of law', type: 'multiple-choice', prompt: 'Rather than amend an entire Act of Parliament, a government Minister updates a detailed road safety regulation under powers already granted by that Act. This regulation is an example of', options: ['delegated legislation', 'common law', 'a constitutional convention', 'customary law'], answer: 'delegated legislation', explanation: 'Delegated legislation is law made by a body other than parliament, under authority parliament has granted through an Act.' },
  { id: 'y11-ls-10', topic: 'legalSystem', syllabusArea: 'Sources of law', type: 'multiple-choice', prompt: 'In interpreting native title claims, Australian courts have recognised traditional laws and practices that existed among Indigenous peoples before European settlement. This is an example of law originating from', options: ['custom', 'delegated legislation', 'a treaty', 'a royal commission'], answer: 'custom', explanation: 'Custom is a traditional source of law, including Indigenous customary law recognised in some Australian court decisions.' },
  { id: 'y11-ls-11', topic: 'legalSystem', syllabusArea: 'Sources of law', type: 'multiple-choice', prompt: 'A court is asked to decide whether the word "vehicle" in an Act includes an electric scooter, a form of transport that did not exist when the Act was written. This process is known as', options: ['statutory interpretation', 'delegated legislation', 'charge negotiation', 'extradition'], answer: 'statutory interpretation', explanation: 'Statutory interpretation is the process courts use to determine the meaning of ambiguous or outdated legislative wording.' },
  { id: 'y11-ls-12', topic: 'legalSystem', syllabusArea: 'Sources of law', type: 'multiple-choice', prompt: 'A NSW court considers a relevant decision from a court in the United Kingdom, which it finds persuasive but is not required to follow. This UK decision is best described as', options: ['persuasive precedent', 'binding precedent', 'delegated legislation', 'statute law'], answer: 'persuasive precedent', explanation: 'Persuasive precedent, such as decisions from other jurisdictions, may influence a court but does not have to be followed.' },
  { id: 'y11-ls-13', topic: 'legalSystem', syllabusArea: 'Sources of law', type: 'multiple-choice', prompt: 'A dispute over which court has the authority to hear a particular case arises because the claim involves both a NSW resident and a Commonwealth government agency. This question concerns', options: ['jurisdiction', 'causation', 'mens rea', 'delegated legislation'], answer: 'jurisdiction', explanation: 'Jurisdiction refers to the authority of a particular court or tribunal to hear and decide a matter.' },
  { id: 'y11-ls-14', topic: 'legalSystem', syllabusArea: 'Classification of law', type: 'multiple-choice', prompt: 'The state prosecutes a man for assault, seeking to punish him on behalf of the community rather than compensate the victim directly. This matter is best classified as', options: ['public law (criminal law)', 'private law (contract law)', 'private law (tort law)', 'international law'], answer: 'public law (criminal law)', explanation: 'Criminal law is a branch of public law, involving the state prosecuting conduct considered harmful to society.' },
  { id: 'y11-ls-15', topic: 'legalSystem', syllabusArea: 'Classification of law', type: 'multiple-choice', prompt: 'Two neighbours privately sue each other over a boundary fence dispute, seeking compensation rather than punishment. This matter is best classified as', options: ['private law', 'public law (criminal)', 'constitutional law', 'international law'], answer: 'private law', explanation: 'Private (civil) law governs disputes between individuals, typically seeking remedies such as compensation.' },
  { id: 'y11-ls-16', topic: 'legalSystem', syllabusArea: 'Classification of law', type: 'multiple-choice', prompt: 'A supplier sues a retailer for breaching the terms of a signed delivery agreement. This dispute falls within which area of private law?', options: ['Contract law', 'Criminal law', 'Constitutional law', 'Administrative law'], answer: 'Contract law', explanation: 'Contract law is a branch of private law dealing with disputes over legally binding agreements.' },
  { id: 'y11-ls-17', topic: 'legalSystem', syllabusArea: 'Classification of law', type: 'multiple-choice', prompt: 'A pedestrian injured by a poorly maintained footpath sues the local council for compensation, arguing the council owed her a duty of care it failed to meet. This claim falls within', options: ['tort law (negligence)', 'criminal law', 'constitutional law', 'international law'], answer: 'tort law (negligence)', explanation: 'Negligence is an area of tort law, a branch of private law concerned with civil wrongs and compensation.' },
  { id: 'y11-ls-18', topic: 'legalSystem', syllabusArea: 'Classification of law', type: 'multiple-choice', prompt: 'A treaty dispute between two countries over shared fishing waters is referred to an international tribunal rather than either country’s domestic courts. This matter falls within', options: ['international law', 'domestic criminal law', 'domestic contract law', 'delegated legislation'], answer: 'international law', explanation: 'International law governs relationships and disputes between states, distinct from a single country’s domestic law.' },
  { id: 'y11-ls-19', topic: 'legalSystem', syllabusArea: 'Law reform', type: 'multiple-choice', prompt: 'Community attitudes toward an outdated law shift significantly, and public pressure builds for parliament to update legislation to reflect modern values. This situation illustrates why', options: ['laws need to be reformed to remain relevant to society', 'delegated legislation must always be repealed', 'custom automatically overrides statute law', 'courts cannot ever change the law'], answer: 'laws need to be reformed to remain relevant to society', explanation: 'Law reform ensures the law keeps pace with changing social values, technology and community expectations.' },
  { id: 'y11-ls-20', topic: 'legalSystem', syllabusArea: 'Law reform', type: 'multiple-choice', prompt: 'After years of public submissions and expert consultation, an independent statutory body publishes a detailed report recommending changes to sentencing laws. This body is most likely a', options: ['law reform commission', 'trade union', 'jury', 'tribunal'], answer: 'law reform commission', explanation: 'Law reform commissions independently research and recommend changes to the law, informing parliamentary reform.' },
];

const individualAndLaw: RawLegalQuizQuestion[] = [
  { id: 'y11-ial-01', topic: 'individualAndLaw', syllabusArea: 'Rights and responsibilities - legal capacity', type: 'multiple-choice', prompt: 'A 10-year-old is found to have taken money from a classmate’s bag. Under NSW law, this is the earliest age at which a child can be held criminally responsible for their actions. This age is', options: ['10 years old', '14 years old', '16 years old', '18 years old'], answer: '10 years old', explanation: 'The minimum age of criminal responsibility in NSW is 10 years old.' },
  { id: 'y11-ial-02', topic: 'individualAndLaw', syllabusArea: 'Rights and responsibilities - legal capacity', type: 'multiple-choice', prompt: 'A 17-year-old wants to sign a mobile phone contract in his own name, but the provider refuses, citing his limited legal capacity to enter binding agreements. This is because full contractual capacity in Australia generally begins at', options: ['18 years old', '16 years old', '14 years old', '21 years old'], answer: '18 years old', explanation: 'The age of majority in Australia is 18, at which point a person generally gains full legal capacity, including to contract.' },
  { id: 'y11-ial-03', topic: 'individualAndLaw', syllabusArea: 'Rights and responsibilities - legal capacity', type: 'multiple-choice', prompt: 'A 16-year-old wishes to marry her long-term partner. Under Australian law, this is only possible if she obtains', options: ['a court order and parental consent, in unusual and limited circumstances', 'no approval at all, as marriage under 18 is automatically valid', 'permission from her school principal', 'a driver’s licence first'], answer: 'a court order and parental consent, in unusual and limited circumstances', explanation: 'Marriage under 18 is only legally possible in limited circumstances, requiring both a court order and parental consent.' },
  { id: 'y11-ial-04', topic: 'individualAndLaw', syllabusArea: 'Rights and responsibilities - legal capacity', type: 'multiple-choice', prompt: 'An 18-year-old receives a letter reminding her that, as an Australian citizen, she is legally required to enrol and vote in federal elections. This obligation reflects that in Australia, voting is', options: ['compulsory for eligible adult citizens', 'optional for all citizens', 'restricted to property owners', 'only required in state elections'], answer: 'compulsory for eligible adult citizens', explanation: 'Voting is compulsory for eligible adult Australian citizens once they reach 18 and are enrolled.' },
  { id: 'y11-ial-05', topic: 'individualAndLaw', syllabusArea: 'Anti-discrimination law', type: 'multiple-choice', prompt: 'A job applicant with a vision impairment is rejected for a desk-based role despite being fully qualified, after the employer assumes she "wouldn’t cope". She may have a claim under the', options: ['Disability Discrimination Act 1992 (Cth)', 'Fair Work Act 2009 (Cth) sentencing provisions', 'Bail Act 2013 (NSW)', 'Native Title Act 1993 (Cth)'], answer: 'Disability Discrimination Act 1992 (Cth)', explanation: 'The Disability Discrimination Act prohibits discrimination against a person on the basis of disability.' },
  { id: 'y11-ial-06', topic: 'individualAndLaw', syllabusArea: 'Anti-discrimination law', type: 'multiple-choice', prompt: 'A landlord refuses to rent an apartment to a family because of their ethnic background. This conduct is most likely unlawful under the', options: ['Racial Discrimination Act 1975 (Cth)', 'Corporations Act 2001 (Cth)', 'Crimes Act 1900 (NSW)', 'Privacy Act 1988 (Cth)'], answer: 'Racial Discrimination Act 1975 (Cth)', explanation: 'The Racial Discrimination Act prohibits discrimination on the basis of race, colour, descent or ethnic origin.' },
  { id: 'y11-ial-07', topic: 'individualAndLaw', syllabusArea: 'Anti-discrimination law', type: 'multiple-choice', prompt: 'A theatre company advertises specifically for a male actor to play a historical male king in a stage production. This is generally lawful because anti-discrimination law recognises', options: ['a genuine occupational qualification exception', 'that anti-discrimination law never applies to employment', 'that only government jobs are covered by the law', 'that acting roles are entirely unregulated'], answer: 'a genuine occupational qualification exception', explanation: 'Anti-discrimination law allows limited exceptions where a specific characteristic is a genuine requirement of a role.' },
  { id: 'y11-ial-08', topic: 'individualAndLaw', syllabusArea: 'Resolving disputes', type: 'multiple-choice', prompt: 'Two business partners in dispute over unpaid invoices sit down together, without any outside help, and agree on a repayment plan. This process is best described as', options: ['negotiation', 'mediation', 'arbitration', 'litigation'], answer: 'negotiation', explanation: 'Negotiation involves parties resolving a dispute directly between themselves, without a third party.' },
  { id: 'y11-ial-09', topic: 'individualAndLaw', syllabusArea: 'Resolving disputes', type: 'multiple-choice', prompt: 'A separating couple meets with a neutral, trained professional who helps them communicate and reach their own agreement about parenting arrangements, without imposing a decision. This process is', options: ['mediation', 'litigation', 'arbitration', 'a criminal trial'], answer: 'mediation', explanation: 'Mediation uses a neutral third party to help parties reach their own voluntary agreement, without imposing a binding outcome.' },
  { id: 'y11-ial-10', topic: 'individualAndLaw', syllabusArea: 'Resolving disputes', type: 'multiple-choice', prompt: 'In a workplace dispute, a Fair Work Commission conciliator actively suggests possible settlement options to both sides, going further than simply facilitating discussion. This process is best described as', options: ['conciliation', 'negotiation only', 'litigation', 'arbitration'], answer: 'conciliation', explanation: 'Conciliation is similar to mediation but the third party takes a more active role, such as suggesting options.' },
  { id: 'y11-ial-11', topic: 'individualAndLaw', syllabusArea: 'Resolving disputes', type: 'multiple-choice', prompt: 'A tenant and landlord in a bond dispute agree in advance to have an independent umpire hear both sides and make a final, binding decision, outside of court. This process is', options: ['arbitration', 'mediation', 'negotiation', 'a criminal prosecution'], answer: 'arbitration', explanation: 'Arbitration involves an independent third party making a binding decision, offering a less formal alternative to court.' },
  { id: 'y11-ial-12', topic: 'individualAndLaw', syllabusArea: 'Resolving disputes', type: 'multiple-choice', prompt: 'A tenant unhappy with the outcome of a rental bond dispute takes the matter to a low-cost, less formal body designed to resolve consumer and tenancy issues without needing a lawyer. This body is most likely', options: ['a tribunal, such as NCAT', 'the Supreme Court', 'the International Criminal Court', 'a royal commission'], answer: 'a tribunal, such as NCAT', explanation: 'Tribunals such as NCAT provide a more accessible, lower-cost alternative to court for resolving many everyday disputes.' },
  { id: 'y11-ial-13', topic: 'individualAndLaw', syllabusArea: 'Resolving disputes', type: 'multiple-choice', prompt: 'Unable to resolve a large commercial dispute through negotiation, one company formally sues the other, engaging lawyers and following strict court procedures. Compared with mediation, this approach to litigation is generally', options: ['more formal, costly and time-consuming', 'faster and cheaper', 'entirely private and confidential', 'unable to produce a binding outcome'], answer: 'more formal, costly and time-consuming', explanation: 'Litigation through the courts is typically more formal, expensive and slower than alternative dispute resolution methods.' },
  { id: 'y11-ial-14', topic: 'individualAndLaw', syllabusArea: 'Law and technology', type: 'multiple-choice', prompt: 'An online retailer collects customer names, addresses and payment details, and must ensure this information is stored securely and not misused. This obligation arises mainly under the', options: ['Privacy Act 1988 (Cth)', 'Bail Act 2013 (NSW)', 'Native Title Act 1993 (Cth)', 'Family Law Act 1975 (Cth)'], answer: 'Privacy Act 1988 (Cth)', explanation: 'The Privacy Act regulates how organisations collect, store and use personal information.' },
  { id: 'y11-ial-15', topic: 'individualAndLaw', syllabusArea: 'Law and technology', type: 'multiple-choice', prompt: 'A teenager who is repeatedly sent threatening and humiliating messages online reports the matter to a federal agency responsible for online safety. This is most likely handled by the', options: ['eSafety Commissioner', 'Director of Public Prosecutions', 'Australian Electoral Commission', 'Fair Work Commission'], answer: 'eSafety Commissioner', explanation: 'The eSafety Commissioner is the federal body responsible for responding to cyberbullying and other online safety issues.' },
  { id: 'y11-ial-16', topic: 'individualAndLaw', syllabusArea: 'Law and technology', type: 'multiple-choice', prompt: 'An inventor develops a new type of solar panel and applies for exclusive legal rights to manufacture and sell it for a set period. This form of legal protection is a', options: ['patent', 'trademark', 'copyright', 'contract'], answer: 'patent', explanation: 'A patent grants an inventor exclusive rights to an invention for a limited period, protecting their intellectual property.' },
  { id: 'y11-ial-17', topic: 'individualAndLaw', syllabusArea: 'Law and technology', type: 'multiple-choice', prompt: 'A business installs CCTV cameras throughout its warehouse to prevent theft, but employees raise concerns about being constantly monitored during their shifts. This scenario illustrates a legal tension between', options: ['security interests and individual privacy', 'criminal law and constitutional law', 'delegated legislation and custom', 'negotiation and litigation'], answer: 'security interests and individual privacy', explanation: 'Surveillance technology raises an ongoing legal and ethical tension between security needs and individual privacy rights.' },
  { id: 'y11-ial-18', topic: 'individualAndLaw', syllabusArea: 'Law and technology', type: 'multiple-choice', prompt: 'A customer clicks "I agree" to a website’s terms and conditions before completing an online purchase. This action creates a legally binding agreement known as', options: ['an e-contract', 'a tort', 'a warrant', 'a treaty'], answer: 'an e-contract', explanation: 'E-commerce has extended contract law to agreements formed electronically, which are generally binding like paper contracts.' },
  { id: 'y11-ial-19', topic: 'individualAndLaw', syllabusArea: 'Law and technology', type: 'multiple-choice', prompt: 'A criminal uses stolen personal details to open a credit card in someone else’s name and rack up thousands of dollars in debt. This conduct is best described as', options: ['identity theft', 'a civil contract dispute', 'a workplace tort', 'defamation'], answer: 'identity theft', explanation: 'Identity theft involves unlawfully using another person’s personal information, often for financial gain.' },
  { id: 'y11-ial-20', topic: 'individualAndLaw', syllabusArea: 'Law and technology', type: 'multiple-choice', prompt: 'A former employee posts false claims on social media accusing his old employer of fraud, causing serious damage to the company’s reputation. The company may have a legal claim for', options: ['defamation', 'treason', 'strict liability', 'extradition'], answer: 'defamation', explanation: 'Defamation law protects individuals and organisations from false statements that damage their reputation, including online.' },
];

const lawInPractice: RawLegalQuizQuestion[] = [
  { id: 'y11-lip-01', topic: 'lawInPractice', syllabusArea: 'Process of legal change', type: 'multiple-choice', prompt: 'After growing public concern about online scams, the federal parliament debates and passes a new Act creating stronger penalties for cyber fraud. This is an example of law reform occurring through', options: ['parliament', 'the courts', 'a trade union', 'customary practice'], answer: 'parliament', explanation: 'Parliament is the primary mechanism for law reform, passing new or amended legislation to address emerging issues.' },
  { id: 'y11-lip-02', topic: 'lawInPractice', syllabusArea: 'Process of legal change', type: 'multiple-choice', prompt: 'A landmark High Court decision establishes a new legal principle that is then applied by lower courts in later, similar cases, effectively changing how the law operates in that area. This shows that legal change can also occur through', options: ['the courts, via the doctrine of precedent', 'delegated legislation alone', 'a royal commission alone', 'customary practice alone'], answer: 'the courts, via the doctrine of precedent', explanation: 'Courts can drive legal change by establishing new precedents that bind future decisions in similar cases.' },
  { id: 'y11-lip-03', topic: 'lawInPractice', syllabusArea: 'Process of legal change', type: 'multiple-choice', prompt: 'Rather than parliament debating a full new Act, a government department quickly updates a technical safety regulation to respond to a new type of e-scooter on the market. This reflects the advantage of', options: ['delegated legislation, which can be updated more quickly than full Acts', 'common law, which cannot be changed', 'international law, which always overrides domestic law', 'customary law, which requires a referendum'], answer: 'delegated legislation, which can be updated more quickly than full Acts', explanation: 'Delegated legislation allows detailed or technical rules to be updated more quickly than a full Act of Parliament.' },
  { id: 'y11-lip-04', topic: 'lawInPractice', syllabusArea: 'Process of legal change', type: 'multiple-choice', prompt: 'After a major public inquiry into institutional failures, an independent body publishes recommendations that later form the basis of new legislation. This inquiry is most likely a', options: ['royal commission', 'jury', 'tribunal hearing', 'private negotiation'], answer: 'royal commission', explanation: 'Royal commissions investigate matters of public importance and often recommend law reform based on their findings.' },
  { id: 'y11-lip-05', topic: 'lawInPractice', syllabusArea: 'Influences on law reform', type: 'multiple-choice', prompt: 'A series of investigative news reports exposing unsafe conditions in aged care leads to a sustained public campaign and, eventually, new legislation. This best illustrates the influence of', options: ['the media on law reform', 'delegated legislation on law reform', 'customary law on law reform', 'jurisdiction on law reform'], answer: 'the media on law reform', explanation: 'Media coverage can raise public awareness and generate pressure that contributes to legal change.' },
  { id: 'y11-lip-06', topic: 'lawInPractice', syllabusArea: 'Influences on law reform', type: 'multiple-choice', prompt: 'Over several decades, community attitudes toward same-sex relationships shifted significantly, contributing to parliament eventually changing the legal definition of marriage. This best illustrates the influence of', options: ['changing social values on law reform', 'delegated legislation on law reform', 'jurisdiction on law reform', 'custom on law reform'], answer: 'changing social values on law reform', explanation: 'Law reform is often driven by evolving community attitudes and values over time.' },
  { id: 'y11-lip-07', topic: 'lawInPractice', syllabusArea: 'Influences on law reform', type: 'multiple-choice', prompt: 'After Australia ratifies an international convention on children’s rights, parliament later amends domestic legislation to ensure Australian law is consistent with its treaty obligations. This shows the influence of', options: ['international law on domestic law reform', 'custom on domestic law reform', 'delegated legislation on international law', 'juries on international law'], answer: 'international law on domestic law reform', explanation: 'Ratifying international treaties can influence and drive changes to a country’s domestic legislation.' },
  { id: 'y11-lip-08', topic: 'lawInPractice', syllabusArea: 'Influences on law reform', type: 'multiple-choice', prompt: 'As online harassment becomes more common with the rise of social media, parliament introduces new offences specifically targeting cyberbullying and image-based abuse. This reform was mainly driven by', options: ['technological change', 'international treaties', 'custom', 'delegated legislation alone'], answer: 'technological change', explanation: 'Rapid technological change frequently creates new harms that existing laws do not adequately address, driving reform.' },
  { id: 'y11-lip-09', topic: 'lawInPractice', syllabusArea: 'Law reform case study', type: 'multiple-choice', prompt: 'In its 1992 decision, the High Court recognised that native title could survive British settlement, overturning the previous legal doctrine that Australia was land belonging to no one before colonisation. This case is known as', options: ['Mabo v Queensland (No 2)', 'R v Smith', 'Donoghue v Stevenson', 'Marbury v Madison'], answer: 'Mabo v Queensland (No 2)', explanation: 'Mabo v Queensland (No 2) (1992) recognised native title in Australian law, overturning the doctrine of terra nullius.' },
  { id: 'y11-lip-10', topic: 'lawInPractice', syllabusArea: 'Law reform case study', type: 'multiple-choice', prompt: 'Following a national postal survey in which a majority of participating Australians supported change, federal parliament passed an Act redefining marriage to include same-sex couples in 2017. This example shows law reform driven by a combination of', options: ['a public survey and parliamentary action', 'a High Court decision alone', 'delegated legislation alone', 'customary law alone'], answer: 'a public survey and parliamentary action', explanation: 'The 2017 marriage law reform followed a national postal survey and was then enacted through an Act of federal parliament.' },
  { id: 'y11-lip-11', topic: 'lawInPractice', syllabusArea: 'Law reform case study', type: 'multiple-choice', prompt: 'After decades of research showing the road toll fell sharply following their introduction, seatbelt laws became one of the clearest examples of law reform driven mainly by', options: ['public health and safety evidence', 'international law', 'customary practice', 'a royal commission alone'], answer: 'public health and safety evidence', explanation: 'Compulsory seatbelt laws are a classic example of legal change driven by clear evidence of public health and safety benefits.' },
  { id: 'y11-lip-12', topic: 'lawInPractice', syllabusArea: 'Access to justice', type: 'multiple-choice', prompt: 'A person facing serious criminal charges but unable to afford a private lawyer is provided with free legal representation funded by the government. This service is known as', options: ['legal aid', 'arbitration', 'a royal commission', 'delegated legislation'], answer: 'legal aid', explanation: 'Legal aid provides government-funded legal assistance to people who cannot otherwise afford representation.' },
  { id: 'y11-lip-13', topic: 'lawInPractice', syllabusArea: 'Access to justice', type: 'multiple-choice', prompt: 'A senior lawyer agrees to represent a community group free of charge in a public interest case, without expecting any payment. This is an example of', options: ['pro bono work', 'legal aid funding', 'arbitration', 'charge negotiation'], answer: 'pro bono work', explanation: 'Pro bono work involves lawyers voluntarily providing free legal services, often to improve access to justice.' },
  { id: 'y11-lip-14', topic: 'lawInPractice', syllabusArea: 'Access to justice', type: 'multiple-choice', prompt: 'Unable to afford a lawyer and not eligible for legal aid, a small business owner appears in court and presents her own case without legal representation. She is best described as a', options: ['self-represented litigant', 'a defendant on bail', 'an arbitrator', 'a juror'], answer: 'self-represented litigant', explanation: 'Self-represented litigants conduct their own case without a lawyer, often due to cost, which can affect access to justice.' },
  { id: 'y11-lip-15', topic: 'lawInPractice', syllabusArea: 'Access to justice', type: 'multiple-choice', prompt: 'A community legal centre reports that many people abandon otherwise valid legal claims simply because court proceedings take too long and cost too much. This is best described as a barrier to', options: ['access to justice', 'statutory interpretation', 'delegated legislation', 'jurisdiction'], answer: 'access to justice', explanation: 'Cost and delay are widely recognised as major barriers to individuals being able to access the justice system effectively.' },
  { id: 'y11-lip-16', topic: 'lawInPractice', syllabusArea: 'Legal literacy and sources', type: 'multiple-choice', prompt: 'A student researching an essay reads the actual text of an Act of Parliament and a recent court judgment on the same issue. These documents are best described as', options: ['primary sources of law', 'secondary sources of law', 'delegated legislation only', 'customary sources only'], answer: 'primary sources of law', explanation: 'Primary sources of law are the original legal materials themselves, such as legislation and court judgments.' },
  { id: 'y11-lip-17', topic: 'lawInPractice', syllabusArea: 'Legal literacy and sources', type: 'multiple-choice', prompt: 'To help understand a complex area of law, a student instead reads a textbook chapter and a law journal article analysing and explaining that law. These materials are best described as', options: ['secondary sources of law', 'primary sources of law', 'binding precedent', 'delegated legislation'], answer: 'secondary sources of law', explanation: 'Secondary sources comment on, explain or analyse the law, rather than being the original legal text itself.' },
  { id: 'y11-lip-18', topic: 'lawInPractice', syllabusArea: 'Legal literacy and sources', type: 'multiple-choice', prompt: 'A student is asked to locate a specific case using its unique identifying reference, including the parties’ names, year and report volume. This reference is known as a', options: ['case citation', 'warrant', 'treaty number', 'bail condition'], answer: 'case citation', explanation: 'A case citation is the standard reference used to identify and locate a specific court decision.' },
  { id: 'y11-lip-19', topic: 'lawInPractice', syllabusArea: 'Legal literacy and sources', type: 'multiple-choice', prompt: 'To understand why parliament passed a particular law, a researcher reads the official transcript of the parliamentary debate that took place before the bill was passed. This transcript is known as', options: ['Hansard', 'a case citation', 'a warrant', 'a writ'], answer: 'Hansard', explanation: 'Hansard is the official transcript of parliamentary debates, useful for understanding the intention behind a law.' },
  { id: 'y11-lip-20', topic: 'lawInPractice', syllabusArea: 'Legal literacy and sources', type: 'multiple-choice', prompt: 'After being passed by both houses of parliament, a bill is formally signed by the Governor-General before it can officially become law. This final step is known as', options: ['Royal Assent', 'ratification', 'extradition', 'charge negotiation'], answer: 'Royal Assent', explanation: 'Royal Assent is the formal approval that turns a bill passed by parliament into an Act, making it law.' },
];

